union={}
order=[]
for s in styles:
    p=subprocess.run(["./executable","-s",s,"--html","--html-styles"], input=b"", capture_output=True)
    txt=p.stdout.decode()
    open(f"/tmp/styles_css/{s}.css","w").write(txt)
    for m in re.finditer(r"/\* (\w+) \*/",txt):
        t=m.group(1)
        if t not in union:
            union[t]=s; order.append(t)
print(order)
print(len(order))
# check any css property names
props=set()
for s in styles:
    txt=open(f"/tmp/styles_css/{s}.css").read()
    for m in re.finditer(r"\{ ([^}]*)\}",txt):
        body=m.group(1)
        for part in body.split(";"):
            part=part.strip()
            if ":" in part:
                props.add(part.split(":")[0].strip())
print(sorted(props))
