import os, re, json, glob, html, xml.etree.ElementTree as ET, subprocess
ROOT="/workspace"
SRC=os.path.join(ROOT,"src")
DATA=os.path.join(SRC,"data")
LEXDIR=os.path.join(DATA,"lexers")
os.makedirs(LEXDIR,exist_ok=True)

def fix_dup_attrs(txt):
    # rename duplicate attributes in start tags
    def repl(m):
        tag=m.group(1); attrs=m.group(2); slash=m.group(3) or ""
        seen={}
        def arepl(am):
            name=am.group(1)
            seen[name]=seen.get(name,0)+1
            if seen[name]>1:
                name=f"{name}__{seen[name]}"
            return f' {name}="{am.group(2)}"'
        newattrs=re.sub(r'\s+([A-Za-z_][\w.-]*)="([^"]*)"', arepl, attrs)
        return f"<{tag}{newattrs}{slash}>"
    return re.sub(r'<([A-Za-z_][\w.-]*)((?:\s+[A-Za-z_][\w.-]*="[^"]*")*)\s*(/?)>', repl, txt)

def get_attrs(el, name):
    out=[]
    if name in el.attrib: out.append(el.attrib[name])
    i=2
    while f"{name}__{i}" in el.attrib:
        out.append(el.attrib[f"{name}__{i}"]); i+=1
    return out

def parse_emitter(el):
    # el is a direct child element representing an emitter (token/bygroups/using/usingself/usingbygroup/include)
    if el.tag=="token":
        return ["token", el.get("type")]
    if el.tag=="bygroups":
        return ["bygroups", [parse_emitter(c) for c in el]]
    if el.tag=="using":
        return ["using", el.get("lexer")]
    if el.tag=="usingself":
        return ["usingself", el.get("state")]
    if el.tag=="usingbygroup":
        sg=None; cg=None; ems=[]
        for c in el:
            if c.tag=="sublexer_name_group": sg=int(c.text.strip())
            elif c.tag=="code_group": cg=int(c.text.strip())
            elif c.tag=="emitters": ems=[parse_emitter(x) for x in c]
        return ["usingbygroup", sg, cg, ems]
    if el.tag=="include":
        return ["include", el.get("state")]
    raise ValueError(f"unknown emitter tag {el.tag}")

def parse_mutator(el):
    if el.tag=="push":
        return ["push", get_attrs(el,"state")]
    if el.tag=="pop":
        return ["pop", int(el.get("depth","1"))]
    if el.tag=="combined":
        return ["combined", get_attrs(el,"state")]
    if el.tag=="include":
        return ["include", el.get("state")]
    raise ValueError(f"unknown mutator {el.tag}")

def parse_rule(el):
    pattern=el.get("pattern")  # None if absent; could be "" if explicit? distinguish: absent -> None
    emitter=None
    mutators=[]
    for c in el:
        if c.tag in ("token","bygroups","using","usingself","usingbygroup"):
            emitter=parse_emitter(c)
        elif c.tag=="include":
            # include alone is stored as emitter-kind include
            emitter=["include", c.get("state")]
        elif c.tag in ("push","pop","combined"):
            mutators.append(parse_mutator(c))
        elif c.tag=="mutators":
            for mc in c:
                mutators.append(parse_mutator(mc))
        else:
            raise ValueError(f"unknown rule child {c.tag}")
    return [pattern, emitter, mutators]

def slugify(name):
    s=name.lower()
    s=s.replace("'","")
    s=re.sub(r'[^a-z0-9]+','_',s).strip('_')
    return s or "lexer"

lexers_index=[]
used_slugs={}
# parse list for order/config of all lexers
list_txt=open("/tmp/list.txt").read()
lexer_section=list_txt.split("\nstyles:")[0]
list_configs=[]
cur=None
for line in lexer_section.splitlines():
    if line.startswith("  ") and not line.startswith("    "):
        if cur: list_configs.append(cur)
        cur={"name":line[2:], "aliases":[], "filenames":[], "mimetypes":[]}
    elif cur is not None and line.startswith("    "):
        body=line[4:]
        if body.startswith("aliases:"): cur["aliases"]=body[len("aliases:"):].strip().split() if body[len("aliases:"):].strip() else []
        elif body.startswith("filenames:"): cur["filenames"]=body[len("filenames:"):].strip().split() if body[len("filenames:"):].strip() else []
        elif body.startswith("mimetypes:"): cur["mimetypes"]=body[len("mimetypes:"):].strip().split() if body[len("mimetypes:"):].strip() else []
if cur: list_configs.append(cur)
print("list lexers",len(list_configs))

xml_by_name={}
for f in glob.glob("/tmp/xmlout/*.xml"):
    txt=open(f,encoding='utf-8').read()
    txt2=fix_dup_attrs(txt)
    try:
        root=ET.fromstring(txt2)
    except Exception as e:
        print("parse fail",f,e); continue
    cfg=root.find("config")
    name=cfg.findtext("name")
    xml_by_name[name]=(f,root,cfg)
print("xml lexers",len(xml_by_name), "missing", [c["name"] for c in list_configs if c["name"] not in xml_by_name])

custom_keys={
 "Common Lisp":"common_lisp", "EmacsLisp":"emacs_lisp", "ERB":"erb", "Go":"go", "Go HTML Template":"go_html_template",
 "Haxe":"haxe", "HTTP":"http", "PHTML":"phtml", "Raku":"raku", "reStructuredText":"rst", "Svelte":"svelte",
}

for lc in list_configs:
    name=lc["name"]
    slug=slugify(name)
    # handle duplicates just in case
    if slug in used_slugs: slug=slug+"_"+str(len(used_slugs))
    used_slugs[slug]=name
    if name in xml_by_name:
        f,root,cfg=xml_by_name[name]
        def get_bool(tag):
            el=cfg.find(tag)
            return (el is not None and (el.text or "").strip().lower()=="true")
        priority=None
        p_el=cfg.find("priority")
        if p_el is not None and p_el.text: priority=float(p_el.text.strip())
        analyse=None
        a_el=cfg.find("analyse")
        if a_el is not None:
            regs=[]
            for r in a_el.findall("regex"):
                regs.append([r.get("pattern"), float(r.get("score"))])
            analyse={"first": (a_el.get("first")=="true"), "regexes":regs}
        states={}
        rules_el=root.find("rules")
        for st in rules_el.findall("state"):
            sname=st.get("name")
            states[sname]=[parse_rule(r) for r in st.findall("rule")]
        data={
            "name":name, "aliases":[e.text for e in cfg.findall("alias")],
            "filenames":[e.text for e in cfg.findall("filename")],
            "mimetypes":[e.text for e in cfg.findall("mime_type")],
            "priority":priority,
            "case_insensitive":get_bool("case_insensitive"),
            "dot_all":get_bool("dot_all"),
            "not_multiline":get_bool("not_multiline"),
            "ensure_nl":get_bool("ensure_nl"),
            "analyse":analyse,
            "states":states,
        }
        # sanity vs list aliases etc: use XML (should match list)
        custom=None
    else:
        data={
            "name":name, "aliases":lc["aliases"], "filenames":lc["filenames"], "mimetypes":lc["mimetypes"],
            "priority":None, "case_insensitive":False,"dot_all":False,"not_multiline":False,"ensure_nl":False,
            "analyse":None, "states":{}, "custom":custom_keys.get(name, slug)
        }
        custom=data["custom"]
    path=os.path.join(LEXDIR, slug+".json")
    with open(path,"w",encoding='utf-8') as fh:
        json.dump(data,fh,ensure_ascii=False,separators=(",",":"))
    lexers_index.append({
        "name":name, "aliases":data["aliases"], "filenames":data["filenames"], "mimetypes":data["mimetypes"],
        "priority":data["priority"], "slug":slug, "custom":data.get("custom"),
        "analyse":data["analyse"], "case_insensitive":data["case_insensitive"], "dot_all":data["dot_all"],
        "not_multiline":data["not_multiline"],
    })
with open(os.path.join(DATA,"lexers_index.json"),"w",encoding='utf-8') as fh:
    json.dump(lexers_index,fh,ensure_ascii=False,separators=(",",":"))

# fallback lexer definition (plaintext rules but name fallback)
fallback={"name":"fallback","aliases":[],"filenames":[],"mimetypes":[],"priority":-1,"case_insensitive":False,"dot_all":False,"not_multiline":False,"ensure_nl":False,"analyse":None,"states":{"root":[[r".+",["token","Text"],[]],[r"\n",["token","Text"],[]]]}}
with open(os.path.join(LEXDIR,"fallback.json"),"w") as fh: json.dump(fallback,fh,separators=(",",":"))

# styles
styles={}
for f in glob.glob("/tmp/styles_css/*.css"):
    name=os.path.basename(f)[:-4]
    styles[name]=open(f,encoding='utf-8').read()
with open(os.path.join(DATA,"styles.json"),"w",encoding='utf-8') as fh:
    json.dump(styles,fh,ensure_ascii=False,separators=(",",":"))
print("styles",len(styles))

# list text and help template (Usage line will be replaced with prog name at runtime - store with placeholder)
open(os.path.join(DATA,"list.txt"),"w",encoding='utf-8').write(list_txt if list_txt.endswith("\n") else list_txt+"\n")
help_txt=open("/tmp/help.txt").read()
open(os.path.join(DATA,"help.txt"),"w",encoding='utf-8').write(help_txt)

# SVG font/style block: run reference once for empty file (style does not matter for font block)
p=subprocess.run(["/workspace/executable","-s","monokai","-l","plaintext","-f","svg"],input=b"",capture_output=True)
s=p.stdout
start=s.find(b"<style>")
end=s.find(b"</style>")+len(b"</style>")
block=s[start:end]
open(os.path.join(DATA,"svg_style.txt"),"wb").write(block)
print("svg block len",len(block))

print("done")
