    if len(s) == 4:
        # #rgb -> #rrggbb
        try:
            r = int(hexpart[0]*2, 16); g = int(hexpart[1]*2, 16); b = int(hexpart[2]*2, 16)
        except Exception:
            raise ColourError(s)
        return (r << 16) | (g << 8) | b
