    inner message ('unknown style element \"x\"' / 'invalid colour \"x\"')."""
    e = StyleEntry()
    if s is None:
        return e
    for el in s.split():
        if el == "bold":
            e.bold = 1
        elif el == "nobold":
            e.bold = -1
        elif el == "italic":
            e.italic = 1
        elif el == "noitalic":
            e.italic = -1
        elif el == "underline":
            e.underline = 1
        elif el == "nounderline":
            e.underline = -1
        elif el == "noinherit":
