        nr, ng, nb = int(r * 0.9), int(g * 0.9), int(b * 0.9)
    else:
        nr = int(r + (255 - r) * 0.1); ng = int(g + (255 - g) * 0.1); nb = int(b + (255 - b) * 0.1)
    return (nr << 16) | (ng << 8) | nb

def synth_line_numbers_colour(v):
    if v is None:
        return 0x7F7F7F
    r, g, b = colour_rgb(v)
    if (r + g + b) / 3.0 / 255.0 > 0.5:
        nr, ng, nb = int(r * 0.5), int(g * 0.5), int(b * 0.5)
    else:
        nr = int((r + 255) * 0.5); ng = int((g + 255) * 0.5); nb = int((b + 255) * 0.5)
    return (nr << 16) | (ng << 8) | nb

# Tri-state: 0 = unset/inherit, 1 = yes, -1 = no
class StyleEntry:
    __slots__ = ("colour", "background", "border", "bold", "italic", "underline", "noinherit")
    def __init__(self, colour=None, background=None, border=None, bold=0, italic=0, underline=0, noinherit=False):
        self.colour = colour
        self.background = background
        self.border = border
        self.bold = bold
        self.italic = italic
        self.underline = underline
        self.noinherit = noinherit
    def copy(self):
        return StyleEntry(self.colour, self.background, self.border, self.bold, self.italic, self.underline, self.noinherit)
    def is_zero_visual(self):
        return (self.colour is None and self.background is None and self.bold != 1 and self.italic != 1 and self.underline != 1)
    def __eq__(self, other):
        if not isinstance(other, StyleEntry):
            return False
        return (self.colour, self.background, self.border, self.bold, self.italic, self.underline) == (other.colour, other.background, other.border, other.bold, other.italic, other.underline)

class StyleEntryError(ValueError):
    pass

def parse_style_entry(s, ctx=None):
    """Parse a style string. ctx is a token type name used in error context
    by callers (they wrap the message). Raises StyleEntryError with the
    inner message ('unknown style element \"x\"' / 'invalid colour \"x\"')."""
    e = StyleEntry()
    if s is None:
        return e
    for el in s.split():
        if el == "bold":
            e.bold = 1
        elif el == "nobold":
            e.bold = -1
        elif el == "italic":
            e.italic = 1
        elif el == "noitalic":
            e.italic = -1
        elif el == "underline":
            e.underline = 1
        elif el == "nounderline":
            e.underline = -1
        elif el == "noinherit":
            e.noinherit = True
        elif el == "inherit":
            e.noinherit = False
        elif el.startswith("bg:"):
            c = el[3:]
            try:
                e.background = parse_colour(c)
            except ColourError:
                raise StyleEntryError(f'invalid colour "{c}"')
        elif el.startswith("border:"):
            c = el[len("border:"):]
            if not c.startswith("#"):
                raise StyleEntryError(f'unknown style element "{el}"')
            try:
                e.border = parse_colour(c)
            except ColourError:
                raise StyleEntryError(f'invalid colour "{c}"')
        elif el.startswith("#"):
            try:
                e.colour = parse_colour(el)
            except ColourError:
                raise StyleEntryError(f'invalid colour "{el}"')
        else:
            raise StyleEntryError(f'unknown style element "{el}"')
    return e

def entry_css_props(e, compact=False):
    """List of (prop, value) in canonical order."""
    cf = colour_compact if compact else colour_css
    out = []
    if e.colour is not None:
        out.append(("color", cf(e.colour)))
    if e.background is not None:
        out.append(("background-color", cf(e.background)))
    if e.bold == 1:
        out.append(("font-weight", "bold"))
    if e.italic == 1:
        out.append(("font-style", "italic"))
    if e.underline == 1:
        out.append(("text-decoration", "underline"))
    return out

def entry_css_string(e):
    # Regular CSS rule body: "color: #fff; background-color: #000" (no trailing ;)
    return "; ".join(f"{k}: {v}" for k, v in entry_css_props(e, compact=False))

def entry_css_string_semi(e):
    # Special Background/PreWrapper form: each prop followed by "; "
    props = entry_css_props(e, compact=False)
    if not props:
        return "; "
    return "".join(f"{k}: {v}; " for k, v in props)

def entry_compact_string(e):
    return ";".join(f"{k}:{v}" for k, v in entry_css_props(e, compact=True))

def cleared_entry(e, bg):
    """Return a copy with fields equal to the background entry cleared."""
    r = e.copy()
    if bg is not None:
        if r.colour == bg.colour:
            r.colour = None
        if r.background == bg.background:
            r.background = None
        if r.bold == bg.bold:
            r.bold = 0
        if r.italic == bg.italic:
            r.italic = 0
        if r.underline == bg.underline:
            r.underline = 0
    return r

class Style:
    def __init__(self, name, entries):
        self.name = name
        self.entries = dict(entries)
        self._cache = {}
        self._synthesise_special()
    def _synthesise_special(self):
        # LineHighlight / LineNumbers / LineNumbersTable synthesis from Background.
        # Use raw resolution without cache interplay.
        bg = self._get_raw("Background")
        if "LineHighlight" not in self.entries:
            hl = StyleEntry(background=clamp_highlight_bg(bg.background))
            self.entries["LineHighlight"] = hl
        if "LineNumbers" not in self.entries:
            self.entries["LineNumbers"] = StyleEntry(colour=synth_line_numbers_colour(bg.colour))
        if "LineNumbersTable" not in self.entries:
            self.entries["LineNumbersTable"] = StyleEntry(colour=synth_line_numbers_colour(bg.colour))
    def _get_raw(self, tt):
        # resolution ignoring special synthesis (special entries may not exist yet)
        return self._resolve(tt)
    def _resolve(self, tt):
        if tt in self._cache:
            return self._cache[tt]
        result = StyleEntry()
        chain = parent_chain(tt)
        for anc in chain:
            ent = self.entries.get(anc)
            if ent is None:
                continue
            if result.colour is None and ent.colour is not None:
                result.colour = ent.colour
            # Background field is not inherited from the Background token
            # itself into regular tokens.
            if result.background is None and ent.background is not None:
                if not (anc == "Background" and tt not in ("Background", "PreWrapper")):
                    result.background = ent.background
            if result.border is None and ent.border is not None:
                result.border = ent.border
            if result.bold == 0 and ent.bold != 0:
                result.bold = ent.bold
            if result.italic == 0 and ent.italic != 0:
                result.italic = ent.italic
            if result.underline == 0 and ent.underline != 0:
                result.underline = ent.underline
            if ent.noinherit:
                result.noinherit = True
                break
        self._cache[tt] = result
        return result
    def get(self, tt):
        if tt not in TOKEN_PARENTS and tt not in ("Text",):
            # unknown token type: resolve by walking name prefixes
            tt = _fallback_token(tt)
        return self._resolve(tt)
    def has(self, tt):
        return tt in self.entries
    def background_entry(self):
        return self._resolve("Background")
    def clone_with(self, replacements):
        entries = dict(self.entries)
        # drop synthesised specials if they were synthesised and a
        # replacement concerns them, they will be replaced / resynthesised.
        for k, v in replacements.items():
            entries[k] = v
        s = object.__new__(Style)
        s.name = self.name
        s.entries = entries
        s._cache = {}
        # if replacement included specials, do not resynthesise over them;
        # if Background changed, the existing special entries (possibly
        # synthesised) stay as in the original (matching builder behaviour
        # for our uses: line/highlight overrides are the replacements).
        return s

def _fallback_token(tt):
    # Map an unknown token type to the nearest known ancestor by longest
    # known prefix among category names.
    candidates = ["NameVariable","NameFunction","NameBuiltin","LiteralString","LiteralNumber","CommentPreproc","Keyword","Name","Literal","Operator","Comment","Generic","Text"]
    for c in candidates:
        if tt.startswith(c):
            return c
    return "Text"

def style_from_css(name, css_text):
    """Build a Style from generated CSS (the --html-styles output).
    Each token line becomes a direct entry for that token type."""
    entries = {}
    for line in css_text.splitlines():
        m = re.match(r"/\* (\w+) \*/ .*\{ (.*) \}\s*$", line)
        if not m:
            m2 = re.match(r"/\* (\w+) \*/ .*\{ (.*)\}\s*$", line)
            if not m2:
                continue
            m = m2
        tok, body = m.group(1), m.group(2)
        if tok in ("LineLink", "LineTableTD", "LineTable", "Line"):
            # static layout rules; may carry extra colour for Line only
            if tok == "Line":
                extra = body.replace("display: flex;", "").strip()
                if extra:
                    entries[tok] = _entry_from_css_body(extra)
            continue
        if tok in ("LineNumbers", "LineNumbersTable"):
            # body starts with static layout props then ";color: ..." or "; ..."
            idx = body.find("0 0.4em;")
            extra = body[idx+len("0 0.4em;"):].strip() if idx >= 0 else ""
            if extra:
                entries[tok] = _entry_from_css_body(extra)
            else:
                entries[tok] = StyleEntry()
            continue
        if tok == "PreWrapper":
            # entry is the same as Background for our purposes
            continue
        entries[tok] = _entry_from_css_body(body)
    return Style(name, entries)

def _entry_from_css_body(body):
    e = StyleEntry()
    body = body.strip()
    if body.endswith(";"):
        body = body[:-1]
    for part in body.split(";"):
        part = part.strip()
        if not part or ":" not in part:
            continue
        k, v = part.split(":", 1)
        k = k.strip(); v = v.strip()
        if k == "color":
            try: e.colour = parse_colour(v)
            except Exception: pass
        elif k == "background-color":
            try: e.background = parse_colour(v)
            except Exception: pass
        elif k == "font-weight" and v == "bold":
            e.bold = 1
        elif k == "font-style" and v == "italic":
            e.italic = 1
        elif k == "text-decoration" and v == "underline":
            e.underline = 1
    return e
