# Regex lexer engine in the style of Pygments/Chroma stateful lexers.
import re, time, json, warnings
from tokens import ALL_TOKEN_TYPES
try:
    from unicode_ranges import RANGES as UNICODE_RANGES
except Exception:
    UNICODE_RANGES = {}

warnings.filterwarnings("ignore", category=DeprecationWarning)

class LexerError(Exception):
    pass

class PanicError(Exception):
    pass

# ---------------------------------------------------------------------------
# Regex translation from .NET/regexp2 syntax to Python `re`.

def _translate_pattern(pat):
    # Handle \p{...} / \pX, \x{...}, \u{...}, possessive quantifiers,
    # atomic groups, keeping track of character classes.
    out = []
    i = 0
    in_class = False
    # for possessive detection, remember last emitted token kind outside class
    while i < len(pat):
        c = pat[i]
        if c == '\\' and i + 1 < len(pat):
            nxt = pat[i+1]
            # \p{...} and \P{...}
            if nxt in ('p', 'P'):
                j = i + 2
                name = None
                if j < len(pat) and pat[j] == '{':
                    k = pat.find('}', j)
                    if k != -1:
                        name = pat[j+1:k]
                        end = k + 1
                    else:
                        end = j
                elif j < len(pat) and pat[j].isalpha():
                    name = pat[j]; end = j + 1
                if name is not None:
                    ranges = UNICODE_RANGES.get(name)
                    if ranges is None:
                        # common fallbacks
                        if name in ('L',):
                            rep = r"A-Za-z" if in_class else r"[^\W\d_]"
                        elif name in ('N', 'Nd'):
                            rep = r"0-9" if in_class else r"[0-9]"
                        elif name in ('Lu',):
                            rep = r"A-Z" if in_class else r"[A-Z]"
                        elif name in ('Ll',):
                            rep = r"a-z" if in_class else r"[a-z]"
                        else:
                            rep = r"\w" if not in_class else r"A-Za-z0-9_"
                        out.append(rep)
                    else:
                        if nxt == 'P' and not in_class:
                            out.append("[^" + ranges + "]")
                        elif nxt == 'P' and in_class:
                            # cannot negate inside a class easily; approximate
                            out.append(ranges)
                        else:
                            out.append(ranges if in_class else "[" + ranges + "]")
                    i = end
                    continue
            if nxt in ('x', 'u') and i + 2 < len(pat) and pat[i+2] == '{':
                k = pat.find('}', i+2)
                if k != -1:
                    try:
                        cp = int(pat[i+3:k], 16)
                        out.append(("\\u%04x" % cp) if cp <= 0xFFFF else ("\\U%08x" % cp))
                        i = k + 1
                        continue
                    except ValueError:
                        pass
            if nxt == 'z':
                out.append(r'\Z'); i += 2; continue
            if nxt == 'G':
                # \G anchors at match start - our match() already anchors
                i += 2; continue
            out.append(pat[i:i+2]); i += 2; continue
        if not in_class and c == '[':
            in_class = True
            out.append(c); i += 1
            # a ']' immediately after '[' or '[^' is a literal
            if i < len(pat) and pat[i] == '^':
                out.append('^'); i += 1
            if i < len(pat) and pat[i] == ']':
                out.append(']'); i += 1
            continue
        if in_class and c == ']':
            in_class = False
            out.append(c); i += 1; continue
        if not in_class and pat.startswith('(?>', i):
            out.append('(?:'); i += 3; continue
        if not in_class and c == '+' and out:
            # possessive quantifier: previous emitted chunk ends with a quantifier
            prev = ''.join(out)
            if prev and (prev[-1] in '*+?' or prev.endswith('}')) :
                # Check it is not a literal plus after e.g. 'a+' meaning
                # possessive 'a++' or 'a*+' etc. Drop this '+'.
                # But pattern 'a+b' has '+' not following a quantifier-end
                # at this point (the '+' itself is the quantifier) - here
                # c=='+' is the *second* character, previous char is the
                # quantifier being made possessive.
                i += 1; continue
        out.append(c); i += 1
    return ''.join(out)

def _fix_unscoped_flag_resets(pat):
    # Convert a leading (?-i) / (?-x) etc (unsupported by Python as a
    # global directive) into a scoped group wrapping the remainder.
    m = re.match(r'^\(\?(-[a-zA-Z]+)\)(.*)$', pat, re.S)
    if m:
        return f"(?{m.group(1)}:{m.group(2)})"
    m = re.match(r'^(\(\?)([a-zA-Z]*-[a-zA-Z]+)\)(.*)$', pat, re.S)
    if m:
        flags = m.group(2)
        return f"(?{flags}:{m.group(3)})"
    return pat

def compile_pattern(pat, flags):
    """Return compiled regex or raise re.error."""
    if pat is None:
        pat = ""
    candidates = []
    t = _translate_pattern(pat)
    candidates.append(t)
    candidates.append(_fix_unscoped_flag_resets(t))
    # wrapped variant (used only if bare fails due to trailing backslash etc is skipped)
    last_err = None
    for cand in candidates:
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                return re.compile(cand, flags)
        except re.error as e:
            last_err = e
            continue
    raise last_err

def go_regex_error_message(pat, err, flags_str):
    wrapped = f"\\G{flags_str}(?:{pat})"
    msg = str(err)
    # Map common cases to the reference (Go) phrasing.
    low = msg.lower()
    if 'unterminated character set' in low or 'unterminated []' in low or ('[' in pat and 'unterminated' in low):
        inner = "unterminated [] set"
    elif 'missing )' in low or 'unterminated subpattern' in low or 'unbalanced parenthesis' in low:
        inner = "missing closing )"
    elif 'bad character range' in low:
        inner = "invalid character class range"
    elif 'invalid repeat' in low or 'min repeat greater' in low or ('repeat' in low and 'greater' in low):
        inner = "invalid repeat count"
    elif 'multiple repeat' in low or 'nothing to repeat' in low:
        inner = "missing argument to repetition operator"
    elif 'unknown extension' in low or 'bad inline flags' in low or 'missing :' in low:
        m = re.search(r'\(\?[^\w\s]?', pat)
        # find offending construct like (?P or (?z
        m2 = re.search(r'\(\?.', pat)
        construct = m2.group(0) if m2 else "(?"
        inner = f"unrecognized grouping construct: {construct}"
    elif 'bad escape' in low and pat.rstrip().endswith('\\'):
        inner = "missing closing )"
    elif 'bad escape' in low:
        m = re.search(r'bad escape (\\.)', msg)
        inner = f"invalid escape sequence: {m.group(1) if m else ''}"
    else:
        inner = re.sub(r' at position \d+$', '', msg)
    return f"error parsing regexp: {inner} in `{wrapped}`"

# ---------------------------------------------------------------------------

class Lexer:
    """A lexer definition (dict in the same shape as our JSON data)."""
    def __init__(self, data, strict=False, source_name=None):
        self.data = data
        self.name = data.get("name", "")
        self.aliases = data.get("aliases") or []
        self.filenames = data.get("filenames") or []
        self.mimetypes = data.get("mimetypes") or []
        self.priority = data.get("priority")
        self.case_insensitive = bool(data.get("case_insensitive"))
        self.dot_all = bool(data.get("dot_all"))
        self.not_multiline = bool(data.get("not_multiline"))
        self.ensure_nl = bool(data.get("ensure_nl"))
        self.analyse = data.get("analyse")
        self.states_raw = data.get("states") or {}
        self.custom = data.get("custom")
        self.strict = strict
        self.source_name = source_name
        self._compiled = None  # state -> list of [pattern, regex, emitter, mutators]
        self._combined_cache = {}
        self.registry = None  # set by registry when loaded through it

    # -- compilation -----------------------------------------------------
    def flags(self):
        f = 0
        if not self.not_multiline:
            f |= re.MULTILINE
        if self.dot_all:
            f |= re.DOTALL
        if self.case_insensitive:
            f |= re.IGNORECASE
        return f
    def flags_str(self):
        s = ""
        if not self.not_multiline:
            s += "m"
        if self.case_insensitive:
            s += "i"
        if self.dot_all:
            s += "s"
        if s and self.not_multiline:
            # observed order without m is "is"
            pass
        return f"(?{s})" if s else ""

    def _validate_token_types(self):
        if not self.strict:
            return
        def check_emitter(em):
            if em is None:
                return
            k = em[0]
            if k == "token":
                if em[1] not in ALL_TOKEN_TYPES:
                    src = self.source_name or self.name
                    raise LexerError(f"{self.name}: failed to compile rules: {src}: {em[1]} does not belong to TokenType values")
            elif k == "bygroups":
                for e in em[1]:
                    check_emitter(e)
            elif k == "usingbygroup":
                for e in em[3]:
