        for sname in self.states_raw.keys():
            compiled[sname] = self._compile_state(sname, flags, ())
        self._compiled = compiled
        return compiled

    def _compile_state(self, sname, flags, stack):
        if sname not in self.states_raw:
            raise LexerError(f'invalid include state "{sname}"')
        if sname in stack:
            return []
        out = []
        for raw in self.states_raw[sname]:
            pattern = raw[0] if len(raw) > 0 else None
            emitter = raw[1] if len(raw) > 1 else None
            mutators = raw[2] if len(raw) > 2 else []
