            if emitter is not None and emitter[0] == "bygroups":
                n = rx.groups
                m = len(emitter[1])
                if n != m:
                    raise LexerError(f"{self.name}: {sname}: {pat}: number of groups {n} does not match number of emitters {m}")
            out.append([pat, rx, emitter, mutators or []])
        return out

    def get_state_rules(self, sname):
        comp = self.compile()
        if sname in comp:
            return comp[sname]
        # combined state?
        if sname in self._combined_cache:
            return self._combined_cache[sname]
        raise PanicError(f"unknown state {sname}")

    def combined_state(self, states):
        name = "__combined_" + "__".join(states)
        if name not in self._combined_cache:
            comp = self.compile()
            rules = []
            for s in states:
                if s not in comp:
                    raise PanicError(f"unknown state {s}")
                rules.extend(comp[s])
            self._combined_cache[name] = rules
        return name

    # -- tokenisation ----------------------------------------------------
    def analyse_text(self, text):
        if self.custom == "go":
            return 0.1 if "package " in text else 0.0
        a = self.analyse
        if not a:
            return 0.0
        flags = 0
        if self.case_insensitive:
            flags |= re.IGNORECASE
        if self.dot_all:
            flags |= re.DOTALL
        total = 0.0
        first = a.get("first")
        for pat, score in a.get("regexes", []):
            try:
                rx = compile_pattern(pat, flags)
            except Exception:
                continue
            if rx.search(text):
                if first:
                    return score
                total += score
        return min(total, 1.0)

