    def _emit_group(self, lexer, em, gtext, tokens):
        if em is None:
            return
        kind = em[0]
        if kind == "token":
            tt = em[1]
            if tt == "Ignore" or gtext == "":
                return
            tokens.append((tt, gtext))
        elif kind == "using":
            sub = self._find_lexer(em[1])
            if sub is None:
                tokens.append(("Text", gtext))
            else:
                tokens.extend(self.tokenise_sub(sub, gtext))
        elif kind == "usingself":
            st = em[1] or "root"
            tokens.extend(self.tokenise_sub(lexer, gtext, st))
        elif kind == "bygroups":
            # not expected nested, treat as text
            tokens.append(("Text", gtext))
        else:
            tokens.append(("Text", gtext))

    def _find_lexer(self, name):
        if self.registry is None:
            return None
        return self.registry.get(name)

def coalesce(tokens):
    out = []
    for tt, val in tokens:
        if val == "" or tt == "Ignore":
            continue
        if out and out[-1][0] == tt:
            out[-1] = (tt, out[-1][1] + val)
        else:
            out.append((tt, val))
    return out
