# Go-compatible JSON string encoding and Go string literal quoting.
import unicodedata

def go_json_escape(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '<':
            out.append('\\u003c')
        elif ch == '>':
            out.append('\\u003e')
        elif ch == '&':
            out.append('\\u0026')
        elif o in (0x2028, 0x2029):
            out.append('\\u%04x' % o)
        elif o < 0x20:
            # Go json uses \b \f shorthand, others \u00xx
            if ch == '\b':
                out.append('\\b')
            elif ch == '\f':
                out.append('\\f')
            else:
                out.append('\\u%04x' % o)
        else:
            out.append(ch)
    return '"' + ''.join(out) + '"'

def _num(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        # Go's json encodes float64 with the shortest representation
        # (strconv.AppendFloat with 'g' semantics for serialisation).
        # json.Marshal uses a custom float encoder close to 'f'/'e'.
        # For trace elapsed values this only needs to be plausible.
        if v == int(v) and abs(v) < 1e15:
            return repr(float(v))
        return repr(v)
    return go_json_escape(str(v))

def go_json_dumps_compact_obj(pairs):
    parts = []
    for k, v in pairs:
        if isinstance(v, str):
            vs = go_json_escape(v)
        else:
            vs = _num(v)
        parts.append(go_json_escape(k) + ":" + vs)
    return "{" + ",".join(parts) + "}"

def _go_is_print(ch):
    if ch == ' ':
        return True
    cat = unicodedata.category(ch)
    return cat[0] in ('L', 'M', 'N', 'P', 'S')

def go_quote(s):
