import os, sys, json, re, zipfile, posixpath
import xml.etree.ElementTree as ET
from lexer_engine import Lexer, LexerError, compile_pattern
from tokens import Style, parse_style_entry, StyleEntryError, ALL_TOKEN_TYPES, style_from_css

DATA_CACHE = {}

def _zip_root():
    p = os.path.abspath(__file__)
    while p and p != os.path.dirname(p):
        if os.path.isfile(p):
            return p
        p = os.path.dirname(p)
    return None

def load_data_bytes(rel):
    if rel in DATA_CACHE:
        return DATA_CACHE[rel]
    # filesystem layout (development): src/data/...
    here = os.path.dirname(os.path.abspath(__file__))
    fs_path = os.path.join(here, "data", rel)
    data = None
    try:
        with open(fs_path, "rb") as f:
            data = f.read()
    except Exception:
        # zipapp layout
        zr = _zip_root()
        if zr and zipfile.is_zipfile(zr):
            with zipfile.ZipFile(zr) as z:
                data = z.read("data/" + rel)
        else:
            raise
    DATA_CACHE[rel] = data
    return data

def load_data_text(rel):
    return load_data_bytes(rel).decode("utf-8")

def load_data_json(rel):
    return json.loads(load_data_text(rel))

# Go path.Base
def go_basename(p):
    if p == "":
        return "."
    p2 = p.rstrip("/")
    if p2 == "":
        return "/"
    idx = p2.rfind("/")
    if idx >= 0:
        return p2[idx+1:]
    return p2

# Go path.Match
def _glob_to_regex(pat):
    out = ["\\A"]
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == '*':
            out.append("[^/]*"); i += 1
        elif c == '?':
            out.append("[^/]"); i += 1
        elif c == '[':
            j = i + 1
            neg = False
            if j < len(pat) and pat[j] == '^':
                neg = True; j += 1
            chars = []
            if j < len(pat) and pat[j] == ']':
                chars.append('\\]'); j += 1
            while j < len(pat) and pat[j] != ']':
                if pat[j] == '\\' and j + 1 < len(pat):
                    chars.append(re.escape(pat[j+1])); j += 2
                else:
                    ch = pat[j]
                    chars.append('\\' + ch if ch in '\\]^' else ch)
                    j += 1
            if j >= len(pat):
                out.append(re.escape('[')); i += 1
            else:
                out.append('[' + ('^' if neg else '') + ''.join(chars) + ']')
                i = j + 1
        elif c == '\\':
            if i + 1 < len(pat):
                out.append(re.escape(pat[i+1])); i += 2
            else:
                out.append('\\\\'); i += 1
        else:
            out.append(re.escape(c)); i += 1
    out.append("\\Z")
    return ''.join(out)

_GLOB_CACHE = {}
def path_match(pat, name):
    rx = _GLOB_CACHE.get(pat)
    if rx is None:
        try:
            rx = re.compile(_glob_to_regex(pat))
        except re.error:
            rx = False
        _GLOB_CACHE[pat] = rx
    if rx is False:
        return False
    return rx.match(name) is not None

class Registry:
    def __init__(self):
        self.index = load_data_json("lexers_index.json")
        self._lexers = {}
        self._by_name = {}
        self._by_alias = {}
        for ent in self.index:
            self._by_name.setdefault(ent["name"].lower(), ent)
        for ent in self.index:
            for a in ent.get("aliases", []):
