        if zr and zipfile.is_zipfile(zr):
            with zipfile.ZipFile(zr) as z:
                data = z.read("data/" + rel)
        else:
            raise
    DATA_CACHE[rel] = data
    return data

def load_data_text(rel):
    return load_data_bytes(rel).decode("utf-8")

def load_data_json(rel):
    return json.loads(load_data_text(rel))

# Go path.Base
def go_basename(p):
    if p == "":
        return "."
    p2 = p.rstrip("/")
    if p2 == "":
        return "/"
    idx = p2.rfind("/")
    if idx >= 0:
        return p2[idx+1:]
    return p2

# Go path.Match
def _glob_to_regex(pat):
    out = ["\\A"]
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == '*':
            out.append("[^/]*"); i += 1
        elif c == '?':
            out.append("[^/]"); i += 1
        elif c == '[':
            j = i + 1
            neg = False
            if j < len(pat) and pat[j] == '^':
                neg = True; j += 1
            chars = []
            if j < len(pat) and pat[j] == ']':
                chars.append('\\]'); j += 1
            while j < len(pat) and pat[j] != ']':
                if pat[j] == '\\' and j + 1 < len(pat):
                    chars.append(re.escape(pat[j+1])); j += 2
                else:
                    ch = pat[j]
                    chars.append('\\' + ch if ch in '\\]^' else ch)
                    j += 1
            if j >= len(pat):
                out.append(re.escape('[')); i += 1
            else:
                out.append('[' + ('^' if neg else '') + ''.join(chars) + ']')
                i = j + 1
        elif c == '\\':
            if i + 1 < len(pat):
                out.append(re.escape(pat[i+1])); i += 2
            else:
                out.append('\\\\'); i += 1
        else:
            out.append(re.escape(c)); i += 1
    out.append("\\Z")
    return ''.join(out)

_GLOB_CACHE = {}
def path_match(pat, name):
    rx = _GLOB_CACHE.get(pat)
    if rx is None:
        try:
            rx = re.compile(_glob_to_regex(pat))
        except re.error:
            rx = False
        _GLOB_CACHE[pat] = rx
    if rx is False:
        return False
    return rx.match(name) is not None

class Registry:
    def __init__(self):
        self.index = load_data_json("lexers_index.json")
        self._lexers = {}
        self._by_name = {}
        self._by_alias = {}
        for ent in self.index:
            self._by_name.setdefault(ent["name"].lower(), ent)
        for ent in self.index:
            for a in ent.get("aliases", []):
                self._by_alias.setdefault(a.lower(), ent)
        self._styles = None

    def load_lexer_by_slug(self, slug):
        if slug in self._lexers:
            return self._lexers[slug]
        data = load_data_json(f"lexers/{slug}.json")
        lx = Lexer(data)
        lx.registry = self
        self._lexers[slug] = lx
        return lx

    def _ent_lexer(self, ent):
        return self.load_lexer_by_slug(ent["slug"])

    def get(self, name):
        if name is None:
            return None
        key = name.lower()
        ent = self._by_name.get(key)
        if ent is None:
            ent = self._by_alias.get(key)
        if ent is None:
            return None
        return self._ent_lexer(ent)

    def match_filename(self, filename):
        base = go_basename(filename)
        best = None
        best_pri = None
        for ent in self.index:
            fns = ent.get("filenames") or []
            ok = False
            for pat in fns:
                if path_match(pat, base):
                    ok = True; break
            if not ok:
                continue
            pri = ent.get("priority")
            if pri is None:
                pri = 1.0
            if best is None or pri > best_pri:
                best = ent; best_pri = pri
        if best is None:
            return None
        return self._ent_lexer(best)

    def match(self, name):
        lx = self.get(name)
        if lx is not None:
            return lx
        return self.match_filename(name)

    def analyse(self, text):
        best = None
        best_score = 0.0
        for ent in self.index:
            if not ent.get("analyse") and ent.get("custom") != "go":
                continue
            lx = self._ent_lexer(ent)
            score = lx.analyse_text(text)
            if score > best_score:
                best_score = score; best = lx
        return best

    def fallback(self):
        if "fallback" not in self._lexers:
            data = load_data_json("lexers/fallback.json")
            lx = Lexer(data); lx.registry = self
            self._lexers["fallback"] = lx
        return self._lexers["fallback"]

    def plaintext(self):
        return self.get("plaintext")

    # styles ------------------------------------------------------------
    def style_names(self):
        # order from list.txt
        txt = load_data_text("list.txt")
        for line in txt.splitlines():
            if line.startswith("styles:"):
                return line[len("styles:"):].strip().split()
        return []

    def get_style(self, name):
        if self._styles is None:
            raw = load_data_json("styles.json")
            self._styles = {k.lower(): (k, v) for k, v in raw.items()}
        ent = self._styles.get((name or "").lower())
        if ent is None:
            return None
        k, css = ent
        return style_from_css(k, css)

    def get_style_css(self, name):
        if self._styles is None:
            raw = load_data_json("styles.json")
            self._styles = {k.lower(): (k, v) for k, v in raw.items()}
        ent = self._styles.get((name or "").lower())
        return ent[1] if ent else None

