# XML loaders (custom lexer / style files)

def _fix_dup_attrs(txt):
    def repl(m):
        tag = m.group(1); attrs = m.group(2); slash = m.group(3) or ""
        seen = {}
        def arepl(am):
            n = am.group(1)
            seen[n] = seen.get(n, 0) + 1
            if seen[n] > 1:
                n = f"{n}__{seen[n]}"
            return f' {n}="{am.group(2)}"'
        newattrs = re.sub(r'\s+([A-Za-z_][\w.-]*)="([^"]*)"', arepl, attrs)
        return f"<{tag}{newattrs}{slash}>"
    return re.sub(r'<([A-Za-z_][\w.-]*)((?:\s+[A-Za-z_][\w.-]*="[^"]*")*)\s*(/?)>', repl, txt)

def _get_attrs(el, name):
    out = []
    if name in el.attrib:
        out.append(el.attrib[name])
    i = 2
    while f"{name}__{i}" in el.attrib:
        out.append(el.attrib[f"{name}__{i}"]); i += 1
    return out

def _parse_emitter_el(el):
    if el.tag == "token":
        return ["token", el.get("type")]
    if el.tag == "bygroups":
        return ["bygroups", [_parse_emitter_el(c) for c in el]]
    if el.tag == "using":
        return ["using", el.get("lexer")]
    if el.tag == "usingself":
        return ["usingself", el.get("state")]
    if el.tag == "usingbygroup":
        sg = cg = None; ems = []
        for c in el:
            if c.tag == "sublexer_name_group": sg = int((c.text or "0").strip())
            elif c.tag == "code_group": cg = int((c.text or "0").strip())
            elif c.tag == "emitters": ems = [_parse_emitter_el(x) for x in c]
        return ["usingbygroup", sg, cg, ems]
    if el.tag == "include":
        return ["include", el.get("state")]
    raise LexerError(f"unexpected element {el.tag}")

def _parse_mutator_el(el):
    if el.tag == "push":
        return ["push", _get_attrs(el, "state")]
    if el.tag == "pop":
        return ["pop", int(el.get("depth", "1"))]
    if el.tag == "combined":
        return ["combined", _get_attrs(el, "state")]
    raise LexerError(f"unexpected element {el.tag}")

def parse_lexer_xml(data_bytes, source_name):
    """Parse a lexer XML file's contents into a Lexer (strict)."""
    try:
        txt = data_bytes.decode("utf-8")
    except Exception:
        txt = data_bytes.decode("utf-8", "replace")
    if "<config" not in txt:
        # The reference searches for a config element
        raise LexerError("could not find <config> element")
    try:
        root = ET.fromstring(_fix_dup_attrs(txt))
    except ET.ParseError as e:
        line = getattr(e, "position", (1, 0))[0]
        raise LexerError(f"XML syntax error on line {line}: {e.msg if hasattr(e,'msg') else e}")
    cfg = root.find("config")
    if cfg is None:
        # maybe root itself is config?
        raise LexerError("could not find <config> element")
    def get_bool(tag):
        el = cfg.find(tag)
        return el is not None and (el.text or "").strip().lower() == "true"
    priority = None
    p = cfg.find("priority")
    if p is not None and p.text:
        try: priority = float(p.text.strip())
        except Exception: priority = None
    analyse = None
    a = cfg.find("analyse")
    if a is not None:
        regs = [[r.get("pattern"), float(r.get("score"))] for r in a.findall("regex") if r.get("score")]
        analyse = {"first": a.get("first") == "true", "regexes": regs}
    states = {}
    rules_el = root.find("rules")
    if rules_el is not None:
        for st in rules_el.findall("state"):
            rules = []
            for r in st.findall("rule"):
                emitter = None; mutators = []
                for c in r:
                    if c.tag in ("token", "bygroups", "using", "usingself", "usingbygroup"):
                        emitter = _parse_emitter_el(c)
                    elif c.tag == "include":
                        emitter = ["include", c.get("state")]
                    elif c.tag in ("push", "pop", "combined"):
                        mutators.append(_parse_mutator_el(c))
                    elif c.tag == "mutators":
                        for mc in c:
                            mutators.append(_parse_mutator_el(mc))
                rules.append([r.get("pattern"), emitter, mutators])
            states[st.get("name")] = rules
    data = {
        "name": cfg.findtext("name") or "",
        "aliases": [e.text for e in cfg.findall("alias") if e.text],
        "filenames": [e.text for e in cfg.findall("filename") if e.text],
        "mimetypes": [e.text for e in cfg.findall("mime_type") if e.text],
        "priority": priority,
        "case_insensitive": get_bool("case_insensitive"),
        "dot_all": get_bool("dot_all"),
        "not_multiline": get_bool("not_multiline"),
        "ensure_nl": get_bool("ensure_nl"),
        "analyse": analyse,
        "states": states,
    }
    lx = Lexer(data, strict=True, source_name=source_name)
    return lx

def parse_style_xml(data_bytes):
    try:
        txt = data_bytes.decode("utf-8")
    except Exception:
        txt = data_bytes.decode("utf-8", "replace")
    if "<" not in txt:
        raise LexerError("EOF")
    try:
        root = ET.fromstring(txt)
    except ET.ParseError as e:
        msg = str(e)
        line = getattr(e, "position", (1, 0))[0]
        if "no element found" in msg:
            raise LexerError("EOF")
        if "unclosed token" in msg or "unexpected end" in msg or "Premature end" in msg:
            raise LexerError(f"XML syntax error on line {line}: unexpected EOF")
        if "not well-formed" in msg:
            raise LexerError(f"XML syntax error on line {line}: unquoted or missing attribute value in element")
        raise LexerError(f"XML syntax error on line {line}: {msg}")
    name = root.get("name")
    if name is None:
        raise LexerError("missing style name attribute")
    entries = {}
    for c in root:
        if c.tag != "entry":
            raise LexerError(f"unexpected element {c.tag}")
        tt = c.get("type")
        if tt is None:
            tt = "None"
        if tt not in ALL_TOKEN_TYPES:
            raise LexerError(f"{tt} does not belong to TokenType values")
        style_str = c.get("style") or ""
        try:
            entries[tt] = parse_style_entry(style_str)
        except StyleEntryError as e:
            raise LexerError(str(e))
    return Style(name, entries)
