            idx = rest.find("\n")
            if idx == -1:
                cur.append((tt, rest))
                rest = ""
                break
            piece = rest[:idx]
            cur.append((tt, piece))
            lines.append((cur, True))
            cur = []
            rest = rest[idx+1:]
    if cur:
