    if tok == "PreWrapper":
        text_cleared = entry_css_string(cleared_entry(style.get("Text"), bg))
        return f"/* PreWrapper */ .{p}chroma {{ {text_cleared}{entry_css_string_semi(bg)}-webkit-text-size-adjust: none; }}\n"
    if tok == "LineLink":
        return f"/* LineLink */ .{p}chroma .{p}lnlinks {{ outline: none; text-decoration: none; color: inherit }}\n"
    if tok == "LineTableTD":
        return f"/* LineTableTD */ .{p}chroma .{p}lntd {{ vertical-align: top; padding: 0; margin: 0; border: 0; }}\n"
    if tok == "LineTable":
        return f"/* LineTable */ .{p}chroma .{p}lntable {{ border-spacing: 0; padding: 0; margin: 0; border: 0; }}\n"
    if tok in ("LineNumbersTable", "LineNumbers"):
        cls = "lnt" if tok == "LineNumbersTable" else "ln"
        cleared = entry_css_string(cleared_entry(style.get(tok), bg))
        return f"/* {tok} */ .{p}chroma .{p}{cls} {{ white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;{cleared} }}\n"
    if tok == "Line":
        cleared = entry_css_string(cleared_entry(style.get(tok), bg))
        return f"/* Line */ .{p}chroma .{p}line {{ display: flex;{cleared} }}\n"
    # regular
    cleared_e = cleared_entry(style.get(tok), bg)
    css = entry_css_string(cleared_e)
    if css == "":
        return ""
    cls = token_class(tok)
    if cls == "":
        return ""
    return f"/* {tok} */ .{p}chroma .{p}{cls} {{ {css} }}\n"

class HTMLFormatter:
    def __init__(self, opts):
        self.o = opts
    # -- style attribute helpers (inline mode) --
    def _compact_cleared(self, style, tt):
        bg = style.get("Background")
        return entry_compact_string(cleared_entry(style.get(tt), bg))
    def _pre_style(self, style):
        bg = style.get("Background")
        text_cleared = entry_compact_string(cleared_entry(style.get("Text"), bg))
        bg_compact = entry_compact_string(bg)
        s = text_cleared + bg_compact + ";-webkit-text-size-adjust:none;"
        if self.o.highlight:
            s += "display:grid;"
        return s
    def _bg_style_semi(self, style):
        bg = style.get("Background")
        return entry_compact_string(bg) + ";"
    def get_style(self, style, tt):
        """Inline style attribute value for a token type (may be '')."""
        bg = style.get("Background")
        if tt == "PreWrapper":
            return self._pre_style(style)
        if tt == "Background":
            return self._bg_style_semi(style)
        if tt == "Line":
            return "display:flex;" + self._compact_cleared(style, "Line")
        if tt in ("LineNumbers", "LineNumbersTable"):
            return ("white-space:pre;-webkit-user-select:none;user-select:none;margin-right:0.4em;"
                    "padding:0 0.4em 0 0.4em;" + self._compact_cleared(style, tt))
        if tt == "LineTable":
            return "border-spacing:0;padding:0;margin:0;border:0;" + self._compact_cleared(style, tt)
        if tt == "LineTableTD":
            return "vertical-align:top;padding:0;margin:0;border:0;" + self._compact_cleared(style, tt)
        if tt == "LineLink":
            return "outline:none;text-decoration:none;color:inherit" + self._compact_cleared(style, tt)
        return self._compact_cleared(style, tt)

    def write_css_public(self, w, style):
        stored = getattr(style, "_stored_css", None)
        overrides = getattr(style, "_css_overrides", ())
        write_css(w, style, prefix="", stored_css=stored, overrides=overrides)

    # main format: write to text writer `w`
    def format(self, tokens, style, w):
        o = self.o
        standalone = not o.only
        if standalone:
            w.write("<html>\n")
            if not o.inline:
                w.write("<style type=\"text/css\">\n")
                stored = getattr(style, "_stored_css", None)
                overrides = getattr(style, "_css_overrides", ())
                write_css(w, style, prefix=o.prefix, stored_css=stored, overrides=overrides)
                # body line
                bg_semi_compact = entry_compact_string(style.get("Background")) + ";"
                w.write(f"body {{ {bg_semi_compact}; }}\n")
                w.write(f"</style><body class=\"{o.prefix}bg\">\n")
            else:
                w.write(f"<body style=\"{self._bg_style_semi(style)}\">\n")
        self._format_body(tokens, style, w)
        if standalone:
            w.write("\n</body>\n</html>\n")

    def _token_html(self, style, tt, val):
        o = self.o
        esc = html_escape(val)
        if o.inline:
            s = self.get_style(style, tt)
            if s:
                return f'<span style="{s}">{esc}</span>'
            return esc
        else:
            cls = token_class(tt)
            if cls:
                return f'<span class="{o.prefix}{cls}">{esc}</span>'
            return esc

    def _format_body(self, tokens, style, w):
        o = self.o
        if o.prevent_pre:
            for tt, val in tokens:
                w.write(self._token_html(style, tt, val))
            return
        lines = split_lines_html(tokens)
        if o.lines and o.lines_table:
            self._write_table(lines, style, w)
            return
        self._write_pre(lines, style, w, with_numbers=o.lines)

    def _write_pre(self, lines, style, w, with_numbers=False):
        o = self.o
        if o.inline:
            w.write(f'<pre style="{self._pre_style(style)}"><code>')
        else:
            w.write(f'<pre class="{o.prefix}chroma"><code>')
        self._write_code_lines(lines, style, w, with_numbers=with_numbers)
        w.write("</code></pre>")

    def _write_code_lines(self, lines, style, w, with_numbers=False):
        o = self.o
        for i, line in enumerate(lines):
            lineno = o.base_line + i
            hl = o.is_highlight(lineno)
            # outer line span
            if o.inline:
                ls = "display:flex;" + self._compact_cleared(style, "Line")
                if hl:
                    ls += " " + self._compact_cleared(style, "LineHighlight")
                w.write(f'<span style="{ls}">')
            else:
                cls = o.prefix + "line"
                if hl:
                    cls += " " + o.prefix + "hl"
                w.write(f'<span class="{cls}">')
            if with_numbers:
                w.write(self._line_number_span(style, lineno, table=False))
            # code line span
            if o.inline:
                cs = self._compact_cleared(style, "CodeLine")
                if cs:
                    w.write(f'<span style="{cs}">')
                else:
                    w.write("<span>")
            else:
                w.write(f'<span class="{o.prefix}cl">')
            for tt, val in line:
                w.write(self._token_html(style, tt, val))
            w.write("</span></span>")

    def _line_number_span(self, style, lineno, table=False):
        o = self.o
        if o.linkable:
            inner = None
            if o.inline:
                a_style = self.get_style(style, "LineLink")
                inner = f'<a style="{a_style}" href="#L{lineno}">{lineno}</a>'
            else:
                inner = f'<a class="{o.prefix}lnlinks" href="#L{lineno}">{lineno}</a>'
            idattr = f' id="L{lineno}"'
        else:
            inner = str(lineno)
            idattr = ""
        if table:
            inner += "\n"
        if o.inline:
            tt = "LineNumbersTable" if table else "LineNumbers"
            st = self.get_style(style, tt)
            return f'<span style="{st}"{idattr}>{inner}</span>'
        else:
            cls = o.prefix + ("lnt" if table else "ln")
            return f'<span class="{cls}"{idattr}>{inner}</span>'

    def _write_table(self, lines, style, w):
        o = self.o
        if o.inline:
            w.write(f'<div style="{self._pre_style(style)}">\n')
            w.write(f'<table style="{self.get_style(style, "LineTable")}"><tr><td style="{self.get_style(style, "LineTableTD")}">\n')
            w.write(f'<pre style="{self._pre_style(style)}">')
        else:
            w.write(f'<div class="{o.prefix}chroma">\n')
            w.write(f'<table class="{o.prefix}lntable"><tr><td class="{o.prefix}lntd">\n')
            w.write(f'<pre class="{o.prefix}chroma">')
        # line numbers column
        for i, line in enumerate(lines):
            lineno = o.base_line + i
            hl = o.is_highlight(lineno)
            num = self._line_number_span(style, lineno, table=True)
            if hl:
                if o.inline:
                    hs = self._compact_cleared(style, "LineHighlight")
                    w.write(f'<span style="{hs}">{num}</span>')
                else:
                    w.write(f'<span class="{o.prefix}hl">{num}</span>')
            else:
                w.write(num)
        # code column
        if o.inline:
            w.write("</pre></td>\n")
            td_style = self.get_style(style, "LineTableTD") + ";width:100%"
            w.write(f'<td style="{td_style}">\n')
        else:
            w.write("</pre></td>\n")
            w.write(f'<td class="{o.prefix}lntd">\n')
        self._write_pre(lines, style, w, with_numbers=False)
        w.write("</td></tr></table>\n")
        w.write("</div>\n")

# ---------- SVG ----------
def svg_escape(s):
    # tab -> 4 spaces, space -> &#160;, xml escapes
    s = s.replace("\t", "    ")
    s = (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;"))
    s = s.replace(" ", "&#160;")
    return s

def _svg_units(s):
    s2 = s.replace("\t", "    ")
    return len(s2.encode("utf-8"))

def format_svg(tokens, style, w, style_block):
    bg = style.get("Background")
    # style_block is the full <style>...</style> bytes/text
    lines = split_lines(tokens)
    # dimensions
    max_units = 0
    for line, terminated in lines:
        u = sum(_svg_units(v) for _, v in line) + (1 if terminated else 0)
        if u > max_units: max_units = u
    width = max_units * 8 if lines else 0
    height = 26 + 17 * len(lines)
    w.write('<?xml version="1.0" encoding="UTF-8"?>\n')
    w.write('<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.0//EN" "http://www.w3.org/TR/2001/REC-SVG-20010904/DTD/svg10.dtd">\n')
    w.write(f'<svg width="{width}px" height="{height}px" xmlns="http://www.w3.org/2000/svg">\n')
    w.write(style_block)
    bg_fill = colour_css(bg.background)  # None -> #-00001
    fg_fill = colour_css(bg.colour)
    w.write(f'<rect width="100%" height="100%" fill="{bg_fill}"/>\n')
    w.write(f'<g font-family="Liberation Mono" font-size="14px" fill="{fg_fill}">\n')
    for i, (line, terminated) in enumerate(lines):
        # rects for tokens with background
        x = 0
        for tt, val in line:
            e = style.get(tt)
            if e.background is not None and e.background != bg.background:
                y = 0.25 + i * 1.2
                w.write(f'<rect id="{svg_escape(val)}" x="{x}ch" y="{y:.6f}em" width="{_svg_units(val)}ch" height="1.2em" fill="{colour_css(e.background)}" />\n')
            x += _svg_units(val)
        y = (i + 1) * 1.2
        w.write(f'<text x="0" y="{y:.6f}em" xml:space="preserve">')
        for tt, val in line:
            e = style.get(tt)
            ce = cleared_entry(e, bg)
            attrs = ""
            if ce.colour is not None:
                attrs += f' fill="{colour_css(ce.colour)}"'
            if ce.bold == 1:
                attrs += ' font-weight="bold"'
            if ce.italic == 1:
                attrs += ' font-style="italic"'
            if ce.underline == 1:
                attrs += ' text-decoration="underline"'
            esc = svg_escape(val)
            if attrs:
                w.write(f'<tspan{attrs}>{esc}</tspan>')
            else:
                w.write(esc)
        if terminated:
            w.write("\n")
        w.write("</text>")
    w.write("\n</g>\n</svg>\n")
