import re, json
from tokens import (StyleEntry, token_class, parent_chain, cleared_entry, colour_css,
                    colour_compact, colour_rgb, entry_compact_string, entry_css_string,
                    entry_css_string_semi, CSS_ORDER)
from gojson import go_quote, go_json_escape

# ---------- line splitting ----------
def split_lines(tokens):
    """Terminal/SVG style: returns list of (line_tokens, terminated)."""
    lines = []
    cur = []
    for tt, val in tokens:
        rest = val
        while rest != "":
            idx = rest.find("\n")
            if idx == -1:
                cur.append((tt, rest))
                rest = ""
                break
            piece = rest[:idx]
            cur.append((tt, piece))
            lines.append((cur, True))
            cur = []
            rest = rest[idx+1:]
    if cur:
        lines.append((cur, False))
    return lines

def split_lines_html(tokens):
    lines = []
    cur = []
    for tt, val in tokens:
        if val == "":
            continue
        start = 0
        while start < len(val):
            idx = val.find("\n", start)
            if idx == -1:
                cur.append((tt, val[start:]))
                start = len(val)
            else:
                cur.append((tt, val[start:idx+1]))
                lines.append(cur)
                cur = []
                start = idx + 1
    if cur:
        lines.append(cur)
    return lines

# ---------- colour palettes ----------
PALETTE16 = [(0,0,0),(128,0,0),(0,128,0),(128,128,0),(0,0,128),(128,0,128),(0,128,128),(192,192,192),(128,128,128),(255,0,0),(0,255,0),(255,255,0),(0,0,255),(255,0,255),(0,255,255),(255,255,255)]
def _build_palette256():
    pal = list(PALETTE16)
    levels = [0,95,135,175,215,255]
    for r in levels:
        for g in levels:
            for b in levels:
                pal.append((r,g,b))
    for i in range(24):
        v = 8 + i*10
        pal.append((v,v,v))
    # dedup by colour, last index wins
    uniq = {}
    for i, c in enumerate(pal):
        uniq[c] = i
    return sorted(((idx, c) for c, idx in uniq.items()))
PALETTE256 = _build_palette256()

def _dist(a, p):
    rmean = (a[0] + p[0]) / 2.0
    dr = a[0]-p[0]; dg = a[1]-p[1]; db = a[2]-p[2]
    return (2 + rmean/256.0)*dr*dr + 4*dg*dg + (2 + (255-rmean)/256.0)*db*db

_nearest_cache = {}
def nearest16(rgb):
    if rgb in _nearest_cache.get(16, {}):
        return _nearest_cache[16][rgb]
    best = None; bestd = None
    for i, c in enumerate(PALETTE16):
        d = _dist(rgb, c)
        if bestd is None or d < bestd:
            bestd = d; best = i
    _nearest_cache.setdefault(16, {})[rgb] = best
    return best

def nearest256(rgb):
    cache = _nearest_cache.setdefault(256, {})
    if rgb in cache:
        return cache[rgb]
    best = None; bestd = None
    for idx, c in PALETTE256:
        d = _dist(rgb, c)
        if bestd is None or d < bestd:
            bestd = d; best = idx
    cache[rgb] = best
    return best

# ---------- terminal ----------
class TerminalFormatter:
    def __init__(self, kind):
        self.kind = kind  # terminal==terminal8
    def _fg(self, v):
        if v is None: return ""
        rgb = colour_rgb(v)
        if self.kind in ("terminal", "terminal8"):
            i = nearest16(rgb)
            if i >= 8:
                return f"\x1b[1m\x1b[{30+i-8}m"
            return f"\x1b[{30+i}m"
        if self.kind == "terminal16":
            i = nearest16(rgb)
            return f"\x1b[{90+i-8}m" if i >= 8 else f"\x1b[{30+i}m"
        if self.kind == "terminal256":
            return f"\x1b[38;5;{nearest256(rgb)}m"
        # 16m
        return f"\x1b[38;2;{rgb[0]};{rgb[1]};{rgb[2]}m"
    def _bg(self, v):
        if v is None: return ""
        rgb = colour_rgb(v)
        if self.kind in ("terminal", "terminal8"):
            i = nearest16(rgb)
            if i >= 8:
                return f"\x1b[1m\x1b[{40+i-8}m"
            return f"\x1b[{40+i}m"
        if self.kind == "terminal16":
            i = nearest16(rgb)
            return f"\x1b[{100+i-8}m" if i >= 8 else f"\x1b[{40+i}m"
        if self.kind == "terminal256":
            return f"\x1b[48;5;{nearest256(rgb)}m"
        return f"\x1b[48;2;{rgb[0]};{rgb[1]};{rgb[2]}m"
    def format(self, tokens, style, w):
        cache = {}
        def seq_for(tt):
            if tt in cache: return cache[tt]
            e = style.get(tt)
            s = ""
            if e.bold == 1: s += "\x1b[1m"
            if e.underline == 1: s += "\x1b[4m"
            if e.italic == 1: s += "\x1b[3m"
            s += self._fg(e.colour)
            s += self._bg(e.background)
            cache[tt] = s
            return s
        for line, terminated in split_lines(tokens):
            for tt, val in line:
                s = seq_for(tt)
                if s:
                    w.write(s + val + "\x1b[0m")
                else:
                    w.write(val)
            if terminated:
                w.write("\n")

# ---------- noop / tokens / json ----------
def format_noop(tokens, style, w):
    for tt, val in tokens:
        w.write(val)

def format_tokens(tokens, style, w):
    for tt, val in tokens:
        w.write(f"&Token{{{tt}, {go_quote(val)}}}\n")

def format_json(tokens, style, w):
    w.write("[\n")
    first = True
    for tt, val in tokens:
        if not first:
            w.write(",\n")
        first = False
        w.write('  {"type":' + go_json_escape(tt) + ',"value":' + go_json_escape(val) + '}')
    w.write("\n]\n")

# ---------- HTML ----------
def html_escape(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
             .replace('"', "&#34;").replace("'", "&#39;"))

class HTMLOptions:
    def __init__(self, **kw):
        self.prefix = kw.get("prefix", "")
        self.only = kw.get("only", False)
        self.inline = kw.get("inline", False)
        self.lines = kw.get("lines", False)
        self.lines_table = kw.get("lines_table", False)
        self.linkable = kw.get("linkable", False)
        self.base_line = kw.get("base_line", 1)
        self.highlight = kw.get("highlight") or []  # list of (lo,hi)
        self.prevent_pre = kw.get("prevent_pre", False)
        self.tab_width = kw.get("tab_width", 8)
        self.all_styles = kw.get("all_styles", False)
    def is_highlight(self, lineno):
        for lo, hi in self.highlight:
            if lo <= lineno <= hi:
                return True
        return False

def _prefix_class(prefix, cls):
    return prefix + cls

def write_css(w, style, prefix="", stored_css=None, overrides=()):
    """overrides: set of token names (LineNumbers/LineHighlight) to
    regenerate from the current style rather than stored CSS."""
    if stored_css is not None:
        for line in stored_css.splitlines(True):
            # patch overridden lines
            m = re.match(r"/\* (\w+) \*/", line)
            if m and m.group(1) in overrides:
                w.write(_css_line_for(style, prefix, m.group(1)))
                continue
            if prefix:
                line = _apply_prefix_to_css_line(line, prefix)
            w.write(line)
        return
    # generate
    order = list(CSS_ORDER)
    for tok in order:
        w.write(_css_line_for(style, prefix, tok))

def _apply_prefix_to_css_line(line, prefix):
    # selectors: .bg, .chroma, .chroma .xx, body handled by caller
    def repl(m):
        comment, rest = m.group(1), m.group(2)
        # replace .xxx selectors in rest before '{'
        brace = rest.find("{")
        head, tail = rest[:brace], rest[brace:]
        head = re.sub(r"\.([A-Za-z0-9_-]+)", lambda mm: "." + prefix + mm.group(1), head)
        return comment + head + tail
    m = re.match(r"(/\* [^*]+ \*/ )(.*)$", line, re.S)
    if not m:
        return line
    return repl(m)

def _css_line_for(style, prefix, tok):
    p = prefix
    bg = style.get("Background")
    if tok == "Background":
        return f"/* Background */ .{p}bg {{ {entry_css_string_semi(bg)}}}\n"
    if tok == "PreWrapper":
        text_cleared = entry_css_string(cleared_entry(style.get("Text"), bg))
        return f"/* PreWrapper */ .{p}chroma {{ {text_cleared}{entry_css_string_semi(bg)}-webkit-text-size-adjust: none; }}\n"
    if tok == "LineLink":
        return f"/* LineLink */ .{p}chroma .{p}lnlinks {{ outline: none; text-decoration: none; color: inherit }}\n"
    if tok == "LineTableTD":
        return f"/* LineTableTD */ .{p}chroma .{p}lntd {{ vertical-align: top; padding: 0; margin: 0; border: 0; }}\n"
    if tok == "LineTable":
        return f"/* LineTable */ .{p}chroma .{p}lntable {{ border-spacing: 0; padding: 0; margin: 0; border: 0; }}\n"
    if tok in ("LineNumbersTable", "LineNumbers"):
        cls = "lnt" if tok == "LineNumbersTable" else "ln"
        cleared = entry_css_string(cleared_entry(style.get(tok), bg))
        return f"/* {tok} */ .{p}chroma .{p}{cls} {{ white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;{cleared} }}\n"
    if tok == "Line":
        cleared = entry_css_string(cleared_entry(style.get(tok), bg))
        return f"/* Line */ .{p}chroma .{p}line {{ display: flex;{cleared} }}\n"
    # regular
    cleared_e = cleared_entry(style.get(tok), bg)
    css = entry_css_string(cleared_e)
    if css == "":
        return ""
    cls = token_class(tok)
    if cls == "":
        return ""
    return f"/* {tok} */ .{p}chroma .{p}{cls} {{ {css} }}\n"

class HTMLFormatter:
    def __init__(self, opts):
        self.o = opts
    # -- style attribute helpers (inline mode) --
    def _compact_cleared(self, style, tt):
        bg = style.get("Background")
        return entry_compact_string(cleared_entry(style.get(tt), bg))
    def _pre_style(self, style):
        bg = style.get("Background")
        text_cleared = entry_compact_string(cleared_entry(style.get("Text"), bg))
        bg_compact = entry_compact_string(bg)
        s = text_cleared + bg_compact + ";-webkit-text-size-adjust:none;"
        if self.o.highlight:
            s += "display:grid;"
        return s
    def _bg_style_semi(self, style):
        bg = style.get("Background")
        return entry_compact_string(bg) + ";"
    def get_style(self, style, tt):
        """Inline style attribute value for a token type (may be '')."""
        bg = style.get("Background")
        if tt == "PreWrapper":
            return self._pre_style(style)
        if tt == "Background":
            return self._bg_style_semi(style)
        if tt == "Line":
            return "display:flex;" + self._compact_cleared(style, "Line")
        if tt in ("LineNumbers", "LineNumbersTable"):
            return ("white-space:pre;-webkit-user-select:none;user-select:none;margin-right:0.4em;"
                    "padding:0 0.4em 0 0.4em;" + self._compact_cleared(style, tt))
        if tt == "LineTable":
