def split_lines(tokens):
    """Terminal/SVG style: returns list of (line_tokens, terminated)."""
    lines = []
    cur = []
    for tt, val in tokens:
        rest = val
        while rest != "":
            idx = rest.find("\n")
            if idx == -1:
                cur.append((tt, rest))
                rest = ""
                break
            piece = rest[:idx]
            cur.append((tt, piece))
            lines.append((cur, True))
            cur = []
            rest = rest[idx+1:]
    if cur:
        lines.append((cur, False))
    return lines

def split_lines_html(tokens):
    lines = []
    cur = []
    for tt, val in tokens:
        if val == "":
            continue
        start = 0
        while start < len(val):
            idx = val.find("\n", start)
            if idx == -1:
                cur.append((tt, val[start:]))
                start = len(val)
            else:
                cur.append((tt, val[start:idx+1]))
                lines.append(cur)
                cur = []
                start = idx + 1
    if cur:
        lines.append(cur)
    return lines

