def _build_palette256():
    pal = list(PALETTE16)
    levels = [0,95,135,175,215,255]
    for r in levels:
        for g in levels:
            for b in levels:
                pal.append((r,g,b))
    for i in range(24):
        v = 8 + i*10
        pal.append((v,v,v))
    # dedup by colour, last index wins
    uniq = {}
    for i, c in enumerate(pal):
        uniq[c] = i
    return sorted(((idx, c) for c, idx in uniq.items()))
