def _dist(a, p):
    rmean = (a[0] + p[0]) / 2.0
    dr = a[0]-p[0]; dg = a[1]-p[1]; db = a[2]-p[2]
    return (2 + rmean/256.0)*dr*dr + 4*dg*dg + (2 + (255-rmean)/256.0)*db*db

_nearest_cache = {}
def nearest16(rgb):
    if rgb in _nearest_cache.get(16, {}):
        return _nearest_cache[16][rgb]
    best = None; bestd = None
    for i, c in enumerate(PALETTE16):
        d = _dist(rgb, c)
        if bestd is None or d < bestd:
            bestd = d; best = i
    _nearest_cache.setdefault(16, {})[rgb] = best
    return best

