def go_clean(path):
    # Go filepath.Clean for unix paths
    if path == "":
        return "."
    rooted = path.startswith("/")
    parts = []
    for comp in path.split("/"):
        if comp in ("", "."):
            continue
        if comp == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            elif not rooted:
                parts.append("..")
            continue
        parts.append(comp)
    out = ("/" if rooted else "") + "/".join(parts)
    if out == "":
        return "/" if rooted else "."
    return out

def go_abs(p):
    p = expand_tilde(p)
