def go_rel(base, target):
    base = go_clean(base); target = go_clean(target)
    bparts = [x for x in base.split("/") if x]
    tparts = [x for x in target.split("/") if x]
    i = 0
    while i < len(bparts) and i < len(tparts) and bparts[i] == tparts[i]:
        i += 1
    rel = [".."] * (len(bparts) - i) + tparts[i:]
