def go_decode(b):
    if isinstance(b, str):
        return b
    out = []
    i = 0
    n = len(b)
    while i < n:
        c = b[i]
        if c < 0x80:
            out.append(chr(c)); i += 1; continue
        # try multi-byte
        ok = False
        for ln in (2, 3, 4):
            if i + ln <= n:
                try:
                    s = b[i:i+ln].decode("utf-8")
                except Exception:
                    continue
                if len(s) == 1 and s.encode("utf-8") == b[i:i+ln]:
                    out.append(s); i += ln; ok = True; break
        if not ok:
            out.append("\ufffd"); i += 1
    return "".join(out)

def go_parse_int64_base0(s):
    """Parse as Go strconv.ParseInt(s, 0, 64). Raise ValueError."""
    if s == "":
        raise ValueError("empty")
    orig = s
    neg = False
    if s[0] in "+-":
        neg = s[0] == "-"
        s = s[1:]
        if s == "":
            raise ValueError(orig)
    # underscores are permitted in base-0 Go literals between digits
    # (approximation: strip them, then validate digits below)
    base = 10
    digits = s
    low = s.lower()
    if low.startswith("0x"):
        base = 16; digits = s[2:]
    elif low.startswith("0b"):
        base = 2; digits = s[2:]
    elif low.startswith("0o"):
        base = 8; digits = s[2:]
    elif len(s) > 1 and s.startswith("0"):
        base = 8; digits = s[1:] if s[1:].replace("_", "") != "" else "0"
        if s == "0":
            digits = "0"
    if digits == "":
        raise ValueError(orig)
    d = digits.replace("_", "")
    if d == "":
        raise ValueError(orig)
    try:
        v = int(d, base)
    except Exception:
        raise ValueError(orig)
    if neg:
        v = -v
    if v < -(1 << 63) or v > (1 << 63) - 1:
        raise ValueError(orig)
    return v

def go_parse_int64_base10(s):
    if s == "":
        raise ValueError(s)
    if not re.fullmatch(r"[+-]?[0-9]+", s):
        raise ValueError(s)
    v = int(s, 10)
    if v < -(1 << 63) or v > (1 << 63) - 1:
        raise OverflowError(s)
