class GoBufferedWriter:
    def __init__(self, size=4096):
        self.size = size
        self.buf = bytearray()
    def _flush_buf(self):
        if self.buf:
            os.write(1, bytes(self.buf))
            self.buf = bytearray()
    def write(self, data):
        if isinstance(data, str):
            data = data.encode("utf-8")
        # Go bufio.Writer.Write algorithm (simplified faithfully)
        while len(data) > (self.size - len(self.buf)):
            if len(self.buf) == 0:
                os.write(1, data)
                return
            need = self.size - len(self.buf)
            self.buf += data[:need]
            data = data[need:]
            self._flush_buf()
        self.buf += data
    def flush(self):
        self._flush_buf()

