def flag_suggestions(name, is_long):
    """Candidates in definition order; each flag yields long then short."""
    out = []
    if not is_long:
        # single-char candidates only
        cands = []
        for f in FLAGS:
            if f.short:
                cands.append(("-" + f.short, f.short))
        for disp, nm in cands:
            if nm.startswith(name) or levenshtein(name, nm) <= 2:
                out.append(disp)
        return out
    for f in FLAGS:
        reps = [("--" + f.long, f.long)]
        if f.short:
            reps.append(("-" + f.short, f.short))
        for disp, nm in reps:
            if nm.startswith(name) or levenshtein(name, nm) <= 2:
                out.append(disp)
    return out

def unknown_flag_error(display, name, is_long):
    sugg = flag_suggestions(name, is_long)
    if not sugg:
        return f"unknown flag {display}"
    quoted = ", ".join(f'"{s}"' for s in sugg)
    if len(sugg) == 1:
        return f"unknown flag {display}, did you mean {quoted}?"
    return f"unknown flag {display}, did you mean one of {quoted}?"

