def go_parse_int64_base10(s):
    if s == "":
        raise ValueError(s)
    if not re.fullmatch(r"[+-]?[0-9]+", s):
        raise ValueError(s)
    v = int(s, 10)
    if v < -(1 << 63) or v > (1 << 63) - 1:
        raise OverflowError(s)
    return v

def levenshtein(a, b):
    if a == b:
        return 0
    la, lb = len(a), len(b)
    if la == 0: return lb
    if lb == 0: return la
    prev = list(range(lb + 1))
    for i in range(1, la + 1):
        cur = [i] + [0] * lb
        for j in range(1, lb + 1):
            cost = 0 if a[i-1] == b[j-1] else 1
            cur[j] = min(prev[j] + 1, cur[j-1] + 1, prev[j-1] + cost)
        prev = cur
    return prev[lb]

# ---------------------------------------------------------------- buffered writer

class DirectWriter:
    def write(self, data):
        if isinstance(data, str):
            data = data.encode("utf-8")
        if data:
            os.write(1, data)
    def flush(self):
        pass

class GoBufferedWriter:
    def __init__(self, size=4096):
        self.size = size
        self.buf = bytearray()
    def _flush_buf(self):
        if self.buf:
            os.write(1, bytes(self.buf))
            self.buf = bytearray()
    def write(self, data):
        if isinstance(data, str):
            data = data.encode("utf-8")
        # Go bufio.Writer.Write algorithm (simplified faithfully)
        while len(data) > (self.size - len(self.buf)):
            if len(self.buf) == 0:
                os.write(1, data)
                return
            need = self.size - len(self.buf)
            self.buf += data[:need]
            data = data[need:]
            self._flush_buf()
        self.buf += data
    def flush(self):
        self._flush_buf()

class TextWriter:
    """Adapter: formatters write str; wraps byte writer."""
    def __init__(self, bw):
        self.bw = bw
    def write(self, s):
        self.bw.write(s)
    def flush(self):
        self.bw.flush()

