BY_LONG = {f.long: f for f in FLAGS}
BY_SHORT = {f.short: f for f in FLAGS if f.short}
FORMATTERS = ["html", "json", "noop", "svg", "terminal", "terminal16", "terminal16m", "terminal256", "terminal8", "tokens"]

def flag_suggestions(name, is_long):
    """Candidates in definition order; each flag yields long then short."""
    out = []
    if not is_long:
        # single-char candidates only
        cands = []
        for f in FLAGS:
            if f.short:
                cands.append(("-" + f.short, f.short))
        for disp, nm in cands:
            if nm.startswith(name) or levenshtein(name, nm) <= 2:
                out.append(disp)
        return out
    for f in FLAGS:
        reps = [("--" + f.long, f.long)]
        if f.short:
            reps.append(("-" + f.short, f.short))
        for disp, nm in reps:
            if nm.startswith(name) or levenshtein(name, nm) <= 2:
                out.append(disp)
    return out

def unknown_flag_error(display, name, is_long):
    sugg = flag_suggestions(name, is_long)
    if not sugg:
        return f"unknown flag {display}"
    quoted = ", ".join(f'"{s}"' for s in sugg)
    if len(sugg) == 1:
        return f"unknown flag {display}, did you mean {quoted}?"
    return f"unknown flag {display}, did you mean one of {quoted}?"

def expected_type_phrase(kind):
    return {"string": "string", "int": "int", "enum": "string", "existingdir": "file"}.get(kind, "string")

class Options:
    pass

def parse_args(argv):
    opts = Options()
    for f in FLAGS:
        setattr(opts, f.dest, f.default)
    opts.files = []
    opts.help_present = False
    opts.version_present = False
    opts.xml_set = False
    positional_only = False
    i = 0
    def add_file(tok):
        if tok == "-":
            opts.files.append("-")
            return
        ap = go_abs(tok)
        try:
            st = os.stat(ap)
        except OSError as e:
            raise ParseError(f"[<files> ...]: stat {ap}: {_errno_str(e)}")
        if statmod.S_ISDIR(st.st_mode):
            raise ParseError(f'[<files> ...]: "{ap}" exists but is a directory')
        opts.files.append(ap)
    def consume_value(fdef, idx):
        # idx = index of token after the flag; returns (value, new_idx)
        if idx >= len(argv):
            raise ParseError(f"--{fdef.long}: expected {expected_type_phrase(fdef.kind)} value but got \"EOL\" (<EOL>)")
        tok = argv[idx]
        if tok != "-" and tok.startswith("-") and tok != "":
            kind = "long flag" if tok.startswith("--") else "short flag"
            raise ParseError(f"--{fdef.long}: expected {expected_type_phrase(fdef.kind)} value but got \"{tok}\" ({kind}); perhaps try --{fdef.long}=\"{tok}\"?")
        return tok, idx + 1
    def set_value(fdef, raw):
        if fdef.kind == "bool":
            low = raw.lower() if isinstance(raw, str) else raw
            if low in ("true", "1", "yes"):
                v = True
            elif low in ("false", "0", "no"):
                v = False
            else:
                raise ParseError(f"--{fdef.long}: bool value must be true, 1, yes, false, 0 or no but got \"{raw}\"")
            setattr(opts, fdef.dest, v)
            if fdef.dest == "help":
                opts.help_present = True
            if fdef.dest == "version":
                opts.version_present = True
        elif fdef.kind == "int":
            try:
                v = go_parse_int64_base0(raw)
            except Exception:
                raise ParseError(f"--{fdef.long}: expected a valid 64 bit int but got \"{raw}\"")
            setattr(opts, fdef.dest, v)
        elif fdef.kind == "existingdir":
            ap = go_abs(raw)
            try:
                st = os.stat(ap)
            except OSError as e:
                raise ParseError(f"--{fdef.long}: stat {ap}: {_errno_str(e)}")
            if not statmod.S_ISDIR(st.st_mode):
                raise ParseError(f'--{fdef.long}: "{ap}" exists but is not a directory')
            setattr(opts, fdef.dest, ap)
            opts.xml_set = True
        else:  # string / enum (deferred)
            setattr(opts, fdef.dest, raw)

    while i < len(argv):
        tok = argv[i]
        if positional_only:
            add_file(tok); i += 1; continue
        if tok == "--":
            positional_only = True; i += 1; continue
        if tok == "-":
            add_file(tok); i += 1; continue
        if tok.startswith("--"):
            body = tok[2:]
            if "=" in body:
                name, raw = body.split("=", 1)
                has_eq = True
            else:
                name, raw, has_eq = body, None, False
            fdef = BY_LONG.get(name)
            if fdef is None:
                raise ParseError(unknown_flag_error("--" + name, name, True))
            if fdef.kind == "bool":
                if has_eq:
                    set_value(fdef, raw)
                else:
                    setattr(opts, fdef.dest, True)
                    if fdef.dest == "help": opts.help_present = True
                    if fdef.dest == "version": opts.version_present = True
                i += 1
            else:
                if has_eq:
                    set_value(fdef, raw); i += 1
                else:
                    raw, i = consume_value(fdef, i + 1)
                    set_value(fdef, raw)
            continue
        if tok.startswith("-") and tok != "-":
            chars = tok[1:]
            j = 0
            consumed_next = False
            while j < len(chars):
                ch = chars[j]
                fdef = BY_SHORT.get(ch)
                if fdef is None:
                    raise ParseError(unknown_flag_error("-" + ch, ch, False))
                if fdef.kind == "bool":
                    setattr(opts, fdef.dest, True)
                    if fdef.dest == "help": opts.help_present = True
                    if fdef.dest == "version": opts.version_present = True
                    j += 1
                    continue
                rest = chars[j+1:]
                if rest != "":
                    set_value(fdef, rest)
                    i += 1
                else:
                    raw, ni = consume_value(fdef, i + 1)
                    set_value(fdef, raw)
                    i = ni
                consumed_next = True
                break
            if not consumed_next:
                i += 1
            continue
        add_file(tok); i += 1
    return opts

