# ---------------------------------------------------------------- XML dump

def _xml_escape_text(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
             .replace('"', "&#34;").replace("'", "&#39;").replace("\t", "&#x9;")
             .replace("\n", "&#xA;").replace("\r", "&#xD;"))

def _xml_escape_attr(s):
    return _xml_escape_text(s)

def _xml_filename(name):
    out = []
    for ch in name.lower():
        if ch.isalnum() and ch.isascii() or ch in "#+-":
            out.append(ch)
        else:
            out.append("_")
    return "".join(out) + ".xml"

def _fmt_score(v):
    if v == int(v):
        return str(int(v))
    return repr(v)

def _serialize_lexer(data):
    lines = []
    A = lines.append
    A("<lexer>")
    A("  <config>")
    A(f"    <name>{_xml_escape_text(data.get('name',''))}</name>")
    for a in data.get("aliases") or []:
        A(f"    <alias>{_xml_escape_text(a)}</alias>")
    for fn in data.get("filenames") or []:
        A(f"    <filename>{_xml_escape_text(fn)}</filename>")
    for m in data.get("mimetypes") or []:
        A(f"    <mime_type>{_xml_escape_text(m)}</mime_type>")
    if data.get("case_insensitive"): A("    <case_insensitive>true</case_insensitive>")
    if data.get("dot_all"): A("    <dot_all>true</dot_all>")
    if data.get("not_multiline"): A("    <not_multiline>true</not_multiline>")
    if data.get("ensure_nl"): A("    <ensure_nl>true</ensure_nl>")
    if data.get("priority") is not None: A(f"    <priority>{_fmt_score(data['priority'])}</priority>")
    an = data.get("analyse")
    if an:
        A(f'    <analyse first="{str(bool(an.get("first"))).lower()}">')
        for pat, score in an.get("regexes", []):
            A(f'      <regex pattern="{_xml_escape_attr(pat)}" score="{_fmt_score(score)}"/>')
        A("    </analyse>")
    A("  </config>")
    A("  <rules>")
    def emitter_xml(em, indent):
        pad = "  " * indent
        if em is None:
            return []
        k = em[0]
        if k == "token":
            return [f'{pad}<token type="{_xml_escape_attr(str(em[1]))}"/>']
        if k == "bygroups":
            out = [f"{pad}<bygroups>"]
            for e in em[1]:
                out += emitter_xml(e, indent + 1)
            out.append(f"{pad}</bygroups>")
            return out
        if k == "using":
            return [f'{pad}<using lexer="{_xml_escape_attr(str(em[1]))}"/>']
        if k == "usingself":
            return [f'{pad}<usingself state="{_xml_escape_attr(str(em[1]))}"/>']
        if k == "include":
            return [f'{pad}<include state="{_xml_escape_attr(str(em[1]))}"/>']
        if k == "usingbygroup":
            out = [f"{pad}<usingbygroup>"]
            out.append(f"{pad}  <sublexer_name_group>{em[1]}</sublexer_name_group>")
            out.append(f"{pad}  <code_group>{em[2]}</code_group>")
            out.append(f"{pad}  <emitters>")
            for e in em[3]:
                out += emitter_xml(e, indent + 2)
            out.append(f"{pad}  </emitters>")
            out.append(f"{pad}</usingbygroup>")
            return out
        return []
    def mutator_xml(mut, indent):
        pad = "  " * indent
        k = mut[0]
        if k == "push":
            states = mut[1]
            if not states:
                return [f"{pad}<push/>"]
            attrs = " ".join(f'state="{_xml_escape_attr(s)}"' for s in states)
            return [f"{pad}<push {attrs}/>"]
        if k == "pop":
            return [f'{pad}<pop depth="{mut[1]}"/>']
        if k == "combined":
            attrs = " ".join(f'state="{_xml_escape_attr(s)}"' for s in mut[1])
            return [f"{pad}<combined {attrs}/>"]
        return []
    for sname, rules in (data.get("states") or {}).items():
        A(f'    <state name="{_xml_escape_attr(sname)}">')
        for rule in rules:
            pattern = rule[0] if len(rule) > 0 else None
            emitter = rule[1] if len(rule) > 1 else None
            mutators = rule[2] if len(rule) > 2 else []
            children = []
            children += emitter_xml(emitter, 4)
            for mut in (mutators or []):
                children += mutator_xml(mut, 4)
            pat_attr = f' pattern="{_xml_escape_attr(pattern)}"' if pattern is not None else ""
            if not children:
                A(f"      <rule{pat_attr}></rule>")
            else:
                A(f"      <rule{pat_attr}>")
                lines.extend(children)
                A("      </rule>")
        A("    </state>")
    A("  </rules>")
    A("</lexer>")
    return "\n".join(lines)

XML_WARNINGS = {
    "Go": 'warning: "Go": unsupported emitter chroma.EmitterFunc: not serialisable\n',
    "Haxe": 'warning: "Haxe": unsupported mutator: not serialisable\n',
    "Raku": 'warning: "Raku": unsupported emitter chroma.EmitterFunc: not serialisable\n',
    "reStructuredText": 'warning: "reStructuredText": unsupported emitter chroma.EmitterFunc: not serialisable\n',
}

def dump_xml(registry, outdir):
    for ent in registry.index:
        name = ent["name"]
        if ent.get("custom"):
            w = XML_WARNINGS.get(name)
            if w:
                try: os.write(2, w.encode())
                except Exception: pass
            continue
        fname = _xml_filename(name)
        dest = os.path.join(outdir, fname)
        if os.path.exists(dest):
            try: os.write(2, f"warning: {dest} already exists\n".encode())
            except Exception: pass
            continue
        lx = registry.load_lexer_by_slug(ent["slug"])
        content = _serialize_lexer(lx.data)
        with open(dest, "wb") as f:
            f.write(content.encode("utf-8"))

