# ---------------------------------------------------------------- run

def _read_input_file(path):
    try:
        with open(path, "rb") as f:
            return f.read()
    except IsADirectoryError:
        raise RuntimeErr(f"read {path}: is a directory")
    except OSError as e:
        raise RuntimeErr(f"open {path}: {_errno_str(e)}")

def run(opts, w):
    registry = Registry()
    # XML dump takes precedence over everything after help/version.
    if opts.xml_set:
        dump_xml(registry, opts.xml)
        return 0
    if opts.list:
        w.write(load_data_text("list.txt"))
        return 0
    # style
    try:
        style = load_style(registry, opts.style)
    except RuntimeErr:
        raise
    style = apply_style_overrides(style, opts)
    # formatter selection (convenience flags win, in order svg, html, json)
    fmt = opts.formatter
    if opts.svg:
        fmt = "svg"
    if opts.html:
        fmt = "html"
    if opts.json:
        fmt = "json"
    # HTML formatter construction (parses highlight ranges) only if html
    html_formatter = None
    if fmt == "html":
        ranges = parse_highlight_ranges(opts.html_highlight)
        html_formatter = HTMLFormatter(HTMLOptions(
            prefix=opts.html_prefix,
            only=opts.html_only,
            inline=opts.html_inline_styles,
            lines=opts.html_lines,
            lines_table=opts.html_lines_table,
            linkable=opts.html_linkable_lines,
            base_line=opts.html_base_line,
            highlight=ranges,
            prevent_pre=opts.html_prevent_surrounding_pre,
            tab_width=opts.html_tab_width,
            all_styles=opts.html_all_styles,
        ))
    if opts.html_styles:
        # default HTML formatter's CSS (prefix ignored)
        tmp = HTMLFormatter(HTMLOptions())
        stored = getattr(style, "_stored_css", None)
        overrides = getattr(style, "_css_overrides", ())
        from formatters import write_css
        write_css(w, style, prefix="", stored_css=stored, overrides=overrides)
        return 0

    fail = opts.fail or PROG == ".lessfilter"

    def trace_sink(line):
        try: os.write(2, line.encode("utf-8", "replace"))
        except Exception: pass
    tokeniser = Tokeniser(registry, trace=opts.trace, trace_sink=trace_sink)

    def do_format(lexer, text):
        try:
            tokens = tokeniser.tokenise(lexer, text)
        except LexerError as e:
            raise RuntimeErr(str(e))
        except PanicError:
            raise
        if fmt == "html":
            html_formatter.format(tokens, style, w)
        elif fmt == "json":
            format_json(tokens, style, w)
        elif fmt == "noop":
            format_noop(tokens, style, w)
        elif fmt == "tokens":
            format_tokens(tokens, style, w)
        elif fmt == "svg":
            block = load_data_bytes("svg_style.txt").decode("utf-8")
            format_svg(tokens, style, w, block)
        else:
            tf = TerminalFormatter(fmt)
            tf.format(tokens, style, w)

    files = opts.files
    if files and opts.check:
        for path in files:
            data = _read_input_file(path)
            text = go_decode(data)
            try:
                lexer, specific = get_lexer(registry, opts, path, text)
            except RuntimeErr:
                raise
            except LexerError as e:
                raise RuntimeErr(str(e))
            try:
                tokens = tokeniser.tokenise(lexer, text)
            except LexerError as e:
                raise RuntimeErr(str(e))
            line = 1; col = 0
            for tt, val in tokens:
                if tt == "Error":
                    from gojson import go_quote
                    w.write(f"{path}:{line}:{col} {go_quote(val)}\n")
                for ch in val:
                    if ch == "\n":
                        line += 1; col = 0
                    else:
                        col += 1
        return 0

    if not files:
        data = sys.stdin.buffer.read()
        text = go_decode(data)
        if fail and text == "":
            raise RuntimeErr("EOF")
        try:
            lexer, specific = get_lexer(registry, opts, opts.filename, text)
        except LexerError as e:
            raise RuntimeErr(str(e))
